"""Dependency-free static build; all listing tables work without JavaScript."""
import csv, html, io, json, pathlib, shutil
ROOT=pathlib.Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'data/competitions.json').read_text()); ROWS=DATA['rows'];CATS=DATA['categories'];CAT={c['id']:c['name'] for c in CATS}
OUT=ROOT/'_site'
if OUT.exists():shutil.rmtree(OUT)
OUT.mkdir()
shutil.copytree(ROOT/'assets',OUT/'assets')
CHECKS=json.loads((ROOT/'docs/source-checks.json').read_text()) if (ROOT/'docs/source-checks.json').exists() else []
LOOKUP={r['url']:r for r in CHECKS}
# Public catalog exposes approved facts plus source references, never inherited prize claims.
for r in ROWS:
 c=LOOKUP.get(r['officialUrl'])
 r['linkCheck']={k:c[k] for k in ('httpStatus','finalUrl','error','checkedAt')} if c else None
(OUT/'assets/catalog.json').write_text(json.dumps(DATA))
shutil.copytree(ROOT/'data',OUT/'data')
shutil.copytree(ROOT/'docs',OUT/'docs')
shutil.copy(ROOT/'COORDINATION.md',OUT/'COORDINATION.md')
def e(x):return html.escape(str(x),quote=True)
def url(prefix,path):return prefix+path
FREE=sum(r['freeCash'] for r in ROWS);PART=sum(r['reviewStatus']=='partial' for r in ROWS)
def stats():
 items=[('Catalog entries',len(ROWS),'206 imported + 3 official findings','▦'),('Free + cash confirmed',FREE,'Not a personal eligibility clearance','↗'),('Categories',len(CATS),'From code to creative work','⊞'),('Needs further review',len(ROWS),'Unknowns stay visible, not assumed','⚑')]
 return '<div class="stats">'+''.join(f'<div class="stat"><span class="stat-label">{a}</span><span class="stat-icon" aria-hidden="true">{d}</span><strong>{b}</strong><small>{c}</small></div>' for a,b,c,d in items)+'</div>'
def layout(title,body,prefix='',page='all',category=''):
 nav=[('all','index.html','▦','All competitions',''),('saved','index.html?view=saved','◇','Saved shortlist',''),('summary','summary/index.html','▤','Executive summary',''),('review','review/index.html','⚑','Flagged for Review',str(len(ROWS)))]
 links=''.join(f'<a href="{prefix+p}" class="{"active" if page==key else ""}" {"aria-current=page" if page==key else ""}><span class="nav-icon" aria-hidden="true">{icon}</span>{label}{f"<span class=nav-num>{num}</span>" if num else ""}</a>' for key,p,icon,label,num in nav)
 cats=''.join(f'<a class="category-link {"active" if category==c["id"] else ""}" href="{prefix}categories/{c["id"]}/index.html" {"aria-current=page" if category==c["id"] else ""}><span class="category-dot" aria-hidden="true"></span>{e(c["name"])}</a>' for c in CATS)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A source-first directory of free-to-enter cash prize competitions. Compare official evidence, AI rules and unresolved claims."><meta name="theme-color" content="#132b25"><title>{e(title)} · Competition Desk</title><link rel="icon" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/styles.css"><script>document.documentElement.classList.add('js')</script><script defer src="{prefix}assets/app.js"></script></head><body data-prefix="{prefix}" data-page="{page}" data-category="{category}"><a class="skip" href="#main">Skip to content</a><aside class="sidebar" id="sidebar" aria-label="Main navigation"><a class="brand" href="{prefix}index.html"><span class="logo" aria-hidden="true">↗</span><span>Competition<small>DESK / CASH PRIZES</small></span></a><nav><p class="nav-label">Workspace</p>{links}<p class="nav-label">Explore categories</p>{cats}</nav><div class="sidebar-foot"><span class="live-dot"></span>Independent. Source-first.<br><span>Free entry ≠ guaranteed winnings.</span><br><a href="https://github.com/sassnarep3-star/Own2" style="color:#b8cdc4">Open research repository ↗</a></div></aside><div class="shell"><header class="topbar"><button class="mobile-menu" aria-label="Toggle navigation" aria-expanded="false" aria-controls="sidebar">☰</button><div class="breadcrumb"><span>Workspace /</span><span>{e(title)}</span></div><div class="top-meta"><a href="{prefix}summary/index.html#methodology">How we verify ↗</a><span class="date-tag">Audit · Nov 01, 2026</span></div></header><main class="content" id="main">{body}<footer class="bottom-note"><span>Competition Desk · Independent research, not an endorsement or income promise.</span><span><a href="{prefix}summary/index.html#methodology">Methodology</a> &nbsp;·&nbsp; <a href="{prefix}review/index.html">Open questions</a> &nbsp;·&nbsp; <a href="{prefix}data/competitions.json" download>Open data ↗</a></span></footer></main></div><dialog id="entry-dialog" aria-labelledby="dialog-title"><div class="dialog-head"><div><span class="eyebrow">Evidence record</span><h2 id="dialog-title">Competition details</h2></div><button class="close-dialog" aria-label="Close competition details">×</button></div><div class="dialog-body" id="dialog-content"></div></dialog><div class="toast" role="status" hidden></div></body></html>'''
def unknown():return '<span class="unknown" aria-label="Unverified; no confirmed value">—<small>Unverified</small></span>'
def row(r):
 f=r['facts'];prize=e(f['prize']) if f['prize'] else unknown();deadline=e(f['deadline']) if f['deadline'] else unknown();fee='<span class="badge free">Free</span>' if f['entryFee']=='Free' else (e(f['entryFee']) if f['entryFee'] else unknown())
 badge='<span class="badge partial">◉ Partial evidence</span>' if r['reviewStatus']=='partial' else '<span class="badge">○ Unverified</span>'
 source=f'<a href="{e(r["officialUrl"])}" target="_blank" rel="noopener noreferrer" aria-label="Operator source for {e(r["name"])}">Source ↗</a>' if r['officialUrl'] else '<span class="badge blocked">Source missing</span>'
 return f'<tr data-id="{e(r["id"])}" id="{e(r["id"])}"><td class="name-cell"><span class="entry-name">{e(r["name"])}</span><span class="entry-category">{e(CAT[r["category"]])}</span></td><td class="prize-cell">{prize}</td><td class="entry-cell">{fee}</td><td class="deadline-cell">{deadline}</td><td>{badge}</td><td class="source-cell">{source}<button class="detail-button js-only" data-detail="{e(r["id"])}" aria-label="Evidence and requirements for {e(r["name"])}">View evidence</button></td><td><button class="save js-only" data-save="{e(r["id"])}" aria-label="Save {e(r["name"])}" aria-pressed="false">◇</button></td></tr>'
def directory(rows,prefix='',category=''):
 options=''.join(f'<option value="{c["id"]}" {"selected" if category==c["id"] else ""}>{e(c["name"])}</option>' for c in CATS)
 return f'''<section class="directory" id="directory" aria-labelledby="directory-title"><div class="directory-header"><h2 id="directory-title">Competition directory <span class="count-pill">{len(rows)}</span></h2><a class="button" id="export" href="{prefix}data/competitions.csv" download><span aria-hidden="true">↓</span> Export CSV</a></div><nav class="directory-tabs" aria-label="Directory views"><a href="{prefix}index.html#directory" data-view="all" aria-current="page">All competitions</a><a href="{prefix}index.html?view=shortlist#directory" data-view="shortlist">Research shortlist</a><a href="{prefix}index.html?view=saved#directory" data-view="saved">Saved <span id="saved-count">0</span></a></nav><div class="filters js-only"><label class="search-wrap"><span aria-hidden="true">⌕</span><span class="sr-only">Search competitions</span><input id="search" type="search" placeholder="Search competitions, categories or AI rules…" autocomplete="off"></label><label><span class="sr-only">Category</span><select id="category"><option value="">All categories</option>{options}</select></label><label><span class="sr-only">Evidence</span><select id="evidence"><option value="">All evidence</option><option value="partial">Partial evidence</option><option value="unverified">Unverified</option></select></label><label><span class="sr-only">Sort competitions</span><select id="sort"><option value="default">Research priority</option><option value="name">Name A–Z</option><option value="deadline">Known deadline first</option></select></label><label class="check"><input type="checkbox" id="free"> Free + cash confirmed only</label></div><div class="filter-meta"><span id="result-count" role="status">Showing {len(rows)} entries · unknown values are not estimates</span><button class="link-button js-only" id="reset">Reset filters</button></div><noscript><p>All entries and sources are available below. Interactive search, saved items and evidence dialogs require JavaScript. <a href="{prefix}data/competitions.json">Download full field-level evidence</a>.</p></noscript><div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable competition comparison table"><table><caption class="sr-only">Competition comparison. An em dash means the value was not confirmed from official evidence.</caption><thead><tr><th scope="col">Competition</th><th scope="col">Cash prize / pool</th><th scope="col">Entry</th><th scope="col">Deadline</th><th scope="col">Evidence</th><th scope="col">Official source</th><th scope="col"><span class="sr-only">Save</span></th></tr></thead><tbody id="entries">{''.join(row(r) for r in rows)}</tbody></table><div id="empty" class="empty" hidden><h3>No matching competitions</h3><p>Try a broader search or reset the filters. Saved items stay in this browser.</p></div></div><div class="table-foot"><span>Every populated fact needs an official citation. Partial evidence is not full verification.</span><span>Audit snapshot: 01 Nov 2026</span></div></section>'''
def write(path,content):
 p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
ordered=sorted(ROWS,key=lambda r:(r['priority'] or 999,r['name'].lower()))
hero='''<section class="hero"><div><span class="eyebrow">Free entry. Real possibilities.</span><h1>Less scrolling.<br>More competing.</h1><p class="intro">Find cash-prize competitions worth a closer look. Compare the facts,<br class="desktop-break"> check the rules, and put your time where it matters.</p></div><div class="hero-note"><b>Good research starts with receipts.</b>Official sources for confirmed facts. Clear flags for everything we couldn’t establish.</div></section>'''
picks='''<div class="section-heading"><div><h2>Your next research move</h2><p>Selected for the AI-agent goal. Editorial priorities, not earnings predictions.</p></div><a class="text-link" href="summary/index.html#priorities">Why these three? ↗</a></div><div class="shortlist">'''
for id,icon,label,desc,amount in [('futureeval-fall-2026','M','AI forecasting','Bot-only tournament. Personal eligibility still needs checking.','$50,000'),('nfl-data-bowl-2027','N','Data & analysis','Build a tracking-data analysis. Entry fee & AI policy unverified.','$100,000'),('gems-2026','G','Machine learning','Map geologic faults. Entry fee & AI policy unverified.','$300,000')]:
 r=next(r for r in ROWS if r['id']==id)
 picks+=f'<article class="pick-card"><div class="pick-top"><span class="pick-icon">{icon}</span><span>{label}</span></div><h3>{e(r["name"])}</h3><p>{desc}</p><div class="pick-bottom"><strong>{amount}<small>pool</small></strong><a href="#{id}" data-open="{id}">View research ↗</a></div></article>'
picks+='</div>'
notice='<div class="notice"><span class="notice-icon" aria-hidden="true">ⓘ</span><span><b>Evidence, not promises.</b> Free + cash confirmed means those two facts only. Eligibility, payout and AI rules may still be unresolved. Unknown values stay blank and flagged.</span></div>'
write('index.html',layout('All competitions',hero+stats()+picks+notice+directory(ordered)))
for c in CATS:
 rs=[r for r in ordered if r['category']==c['id']]
 intro=f'<section class="hero"><div><span class="eyebrow">Explore a category</span><h1>{e(c["name"])}</h1><p class="intro">{len(rs)} catalog entries. Category labels are organizational, not a guarantee of free entry or cash prizes.</p></div></section>'
 write(f'categories/{c["id"]}/index.html',layout(c['name'],intro+notice+directory(rs,'../../',c['id']),'../../','category',c['id']))
# Executive summary and source-site audit are factual, scoped to observed markup and data.
summary=f'''<section class="hero"><div><span class="eyebrow">The brief / 01 Nov 2026</span><h1>Executive summary.</h1><p class="intro">A useful directory is a decision tool, not a collection of optimistic prize claims.</p></div><a class="button" href="../docs/EXECUTIVE_SUMMARY.md" download>↓ Download brief</a></section>{stats()}<div class="summary-grid"><div><section class="panel"><h2>What we found</h2><p>The original catalog contains <b>206 entries across nine categories</b>. All are preserved, alongside three specific competitions found on official pages. The catalog combines platforms, individual contests, mini-leagues, non-cash games, pool tools and historical promotions. It is not a list of 206 currently open, free cash competitions.</p><p><b>{PART} rows have some independently inspected official evidence; {len(ROWS)-PART} have no independently confirmed contest fields.</b> No row is cleared on every requirement. All {len(ROWS)} remain on the Flagged for Review page because at least one critical field is unknown.</p><p><b>{FREE} rows have explicit free-entry and cash-prize evidence.</b> This includes the Metaculus platform directory, its specific Fall FutureEval event, and Wergle Flomp. These are not three distinct entry-ready recommendations: the platform and event overlap, and the writing contest prohibits AI-generated text.</p><h3>Bottom line</h3><p>Start with the FutureEval bot tournament’s rules and setup. Investigate the NFL Big Data Bowl and GEMS task requirements next, but do not assume free entry or permission to use generative AI. ARC Prize has a near-immediate submission deadline. Do not spend on deposits or compute until the entry conditions, data license and tool rules are established.</p></section><section class="panel" id="priorities"><h2>Where to spend research time</h2><ol><li><b>FutureEval Fall 2026:</b> $50,000 pool, bot-only, closes January 6, 2027. Strongest explicit match for AI-agent participation among pages inspected. Scored questions have short windows, and joining late may be a disadvantage. <a href="https://www.metaculus.com/tournament/fall-futureeval-2026/">Official event</a> · <a href="https://www.metaculus.com/notebooks/38928/ai-benchmark-resources/">Rules &amp; setup</a>.</li><li><b>NFL Big Data Bowl 2027:</b> $100,000 total; January 6, 2027, 23:59 UTC deadline. Data analysis and a public notebook/writeup are required. Free entry, full eligibility and AI assistance remain unconfirmed. <a href="https://www.kaggle.com/competitions/nfl-big-data-bowl-2027/rules">Official rules</a>.</li><li><b>GEMS Prize:</b> $300,000 pool; December 3, 2026, 23:59 UTC deadline. Algorithm and geospatial data task. Entry fee, full eligibility and generative-AI permission remain unconfirmed. <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/">Official overview</a>.</li><li><b>ARC Prize:</b> $2 million across three tracks; submissions November 2 and papers November 8. No API access during Kaggle evaluation; open-source requirements apply. Entry fee and full eligibility not reconfirmed. <a href="https://arcprize.org/competitions/2026">Official terms</a>.</li></ol><p>This order is an editorial research recommendation for the stated goal. There are no fabricated win probabilities, estimated hourly earnings, difficulty scores or guaranteed returns.</p></section></div><div><section class="panel"><h2>Original site audit</h2><ul><li><b>Discoverability:</b> its landing page explicitly says “No search box, no filters.” The new directory adds both, with category subpages and saved research.</li><li><b>Reading load:</b> long cards repeat signup, payout and terms sections for 206 entries. A compact comparison table now puts unknowns beside confirmed facts.</li><li><b>Inconsistent dates:</b> source header says “Pass C · 17 Aug 2026”; data says reviewed August 19, pass S. Neither is treated as a fresh verification date.</li><li><b>Overbroad free count:</b> original “True free paths” is derived from full or partial freePath labels, not independently checked current free-cash rules.</li><li><b>Tax statement:</b> the original blanket $600+ statement is not carried over as advice. Current reporting duties require authoritative, jurisdiction-specific review.</li><li><b>Mobile:</b> original markup was inspected, not device-tested here. The replacement is tested separately at mobile widths; it does not claim a measured usability score for the original.</li></ul><p><a href="https://karagemop466-tech.github.io/FreeMoneyApps/">Original live site</a> · <a href="https://github.com/karagemop466-tech/FreeMoneyApps/blob/main/index.html">Original markup</a> · <a href="https://github.com/karagemop466-tech/FreeMoneyApps/blob/main/assets/js/app.js">Original counting logic</a></p></section><section class="panel" id="methodology"><h2>How verification works</h2><ol><li>Preserve each original row with its import provenance.</li><li>Check linked operator pages. Network errors and HTTP failures are recorded, not called “scams” or assumed to be permanent dead links.</li><li>Populate a fact only after inspecting official text. Each populated field has a URL, excerpt, check date and method.</li><li>Leave unknown values empty in JSON/CSV; display an em dash marked Unverified.</li><li>Flag missing source links, delegated rules, unsupported prizes, personal eligibility and AI restrictions.</li></ol><p>HTTP 200 means a page responded; it does not verify a contest. A general platform homepage does not prove a named mini-league exists. Imported categories and names are provenance labels, not independently confirmed operator claims.</p><p>Expected-value ranking is not possible without reliable entrants, win rates, time, costs and payout data. None are invented.</p><p><a href="../docs/import-provenance.json">Pinned import provenance</a> · <a href="../data/competitions.json">Field-level evidence</a> · <a href="../docs/source-checks.json">URL audit</a></p></section></div></div>'''
write('summary/index.html',layout('Executive summary',summary,'../','summary'))
http_counts={}
for c in CHECKS:
 key=str(c['httpStatus'] or 'Network error');http_counts[key]=http_counts.get(key,0)+1
broken=[c for c in CHECKS if c['httpStatus'] and c['httpStatus']>=400]
review=f'''<section class="hero"><div><span class="eyebrow">Open evidence, visible unknowns</span><h1>Flagged for Review.</h1><p class="intro review-intro">Publishing an unresolved item does not verify it. Every catalog entry below has at least one missing requirement. No personal information or manual response is needed to use this research.</p></div></section><div class="notice warning"><span aria-hidden="true">⚑</span><span><b>Not entry-ready.</b> Full personal eligibility and payout terms have not been established for any row. No competition entry, deposit, account creation or prize claim was made.</span></div><div class="panel"><h2>Link audit &amp; source limitations</h2><p>{len(CHECKS)} unique inherited signup, rules and terms URLs were attempted in GitHub Actions. {len(broken)} returned an HTTP error; other network errors may reflect blocking or timeouts. Responses can vary by region, browser and date. HTTP success does not prove that the named competition exists.</p><p><a href="../docs/source-checks.json">Full dated URL evidence →</a> · <a href="../data/imported-ledger.json">Original claims, explicitly unverified →</a></p><p>One inherited entry (The Draft Pro) links only to a press-release distributor. It is retained in this review queue with an official-source-missing flag, not represented as verified. Several mini-leagues point at the FPL host rather than the mini-league organizer. Historical years embedded in URLs are flags to inspect, not proof that an event is expired.</p><p>Direct sandbox operator-domain requests are restricted. Official page text was inspected through the available page reader; a separate GitHub Actions run attempted all inherited URLs. No claim was accepted solely because the upstream directory labeled a source “official”.</p></div><section class="directory"><div class="directory-header"><h2>Row-by-row review queue <span class="count-pill">{len(ROWS)}</span></h2></div><div class="filters js-only"><label class="search-wrap"><span aria-hidden="true">⌕</span><span class="sr-only">Search review queue</span><input id="review-search" type="search" placeholder="Search names, missing requirements or link results…"></label></div><p class="filter-meta" id="review-count" role="status">{len(ROWS)} entries need review</p><div class="table-scroll" tabindex="0" role="region" aria-label="Review queue"><table class="review-table"><caption class="sr-only">Unresolved requirements and official source candidates for every entry</caption><thead><tr><th>Entry / category</th><th>Unresolved requirements &amp; findings</th><th>URL reachability</th><th>Source / evidence</th></tr></thead><tbody>'''
for r in ordered:
 c=LOOKUP.get(r['officialUrl']);status=(f'HTTP {c["httpStatus"]}' if c['httpStatus'] else 'Network error') if c else 'Not checked / missing'
 flags=r['flags']+r['notes'];links=f'<a href="{e(r["officialUrl"])}" target="_blank" rel="noopener noreferrer">Operator source ↗</a>' if r['officialUrl'] else '<span class="badge blocked">Official source missing</span>'
 if r.get('provenanceUrl'):links+=f'<br><a href="{e(r["provenanceUrl"])}">Non-official provenance ↗</a>'
 review+=f'<tr data-review="{e((r["name"]+" "+" ".join(flags)+" "+status).lower())}"><td><b>{e(r["name"])}</b><span class="entry-category">{e(CAT[r["category"]])}</span></td><td>{"<br>".join(e(f) for f in flags)}</td><td>{e(status)}<span class="entry-category">{e(c["checkedAt"][:10]) if c else ""}</span></td><td>{links}<button class="detail-button js-only" data-detail="{e(r["id"])}">View full evidence</button></td></tr>'
review+='</tbody></table></div></section>'
write('review/index.html',layout('Flagged for Review',review,'../','review'))
write('404.html',layout('Page not found','<div class="panel"><h1>That page moved.</h1><p><a href="/Own2/index.html">Return to the competition directory →</a></p></div>','/Own2/'))
# Plain CSV leaves unconfirmed values genuinely empty.
buf=io.StringIO();w=csv.writer(buf);headers=['id','name','category','entryFee','prize','deadline','eligibility','payout','aiPolicy','officialUrl','reviewStatus','unknownFields'];w.writerow(headers)
for r in ordered:w.writerow([r['id'],r['name'],CAT[r['category']],*[r['facts'][k] for k in ('entryFee','prize','deadline','eligibility','payout','aiPolicy')],r['officialUrl'],r['reviewStatus'],'; '.join(r['unknownFields'])])
write('data/competitions.csv',buf.getvalue());write('.nojekyll','')
print(f'Built {len(ROWS)} entries, {len(CATS)} category pages, summary and review; {len(CHECKS)} URL checks.')
